663	// handleLifecycleSubagentStart handles subagent start: captures pre-task state.
664	func handleLifecycleSubagentStart(ctx context.Context, ag agent.Agent, event *agent.Event) error {
665		logCtx := logging.WithAgent(logging.WithComponent(ctx, "lifecycle"), ag.Name())
666		logging.Info(logCtx, "subagent started",
667			slog.String("event", event.Type.String()),
668			slog.String("session_id", event.SessionID),
669			slog.String("tool_use_id", event.ToolUseID),
670			slog.String("transcript", event.SessionRef),
671		)
672	
673		// Capture pre-task state
674		if err := CapturePreTaskState(ctx, event.ToolUseID); err != nil {
675			return fmt.Errorf("failed to capture pre-task state: %w", err)
676		}
677	
678		return nil
679	}
