813	// --- Helper functions ---
814	
815	// resolveTranscriptOffset determines the transcript offset to use for parsing.
816	// Prefers pre-prompt state, falls back to session state.
817	func resolveTranscriptOffset(ctx context.Context, preState *PrePromptState, sessionID string) int {
818		logCtx := logging.WithComponent(ctx, "lifecycle")
819		if preState != nil && preState.TranscriptOffset > 0 {
820			logging.Debug(logCtx, "pre-prompt state found, parsing transcript from offset",
821				slog.Int("offset", preState.TranscriptOffset))
822			return preState.TranscriptOffset
823		}
824	
825		// Fall back to session state
826		sessionState, loadErr := strategy.LoadSessionState(ctx, sessionID)
827		if loadErr != nil {
828			logging.Warn(logCtx, "failed to load session state",
829				slog.String("error", loadErr.Error()))
830			return 0
831		}
832		if sessionState != nil && sessionState.CheckpointTranscriptStart > 0 {
833			logging.Debug(logCtx, "session state found, parsing transcript from offset",
834				slog.Int("offset", sessionState.CheckpointTranscriptStart))
835			return sessionState.CheckpointTranscriptStart
836		}
837	
838		return 0
839	}
840	
841	// parseTranscriptForCheckpointUUID is a thin wrapper around transcript parsing for checkpoint UUID lookup.
842	// Returns parsed transcript lines for use with FindCheckpointUUID.
843	func parseTranscriptForCheckpointUUID(transcriptPath string) ([]transcriptLine, error) {
844		lines, err := transcript.ParseFromFileAtLine(transcriptPath, 0)
845		if err != nil {
846			return nil, fmt.Errorf("parsing transcript for checkpoint UUID: %w", err)
847		}
848		return lines, nil
849	}
850	
851	// transitionSessionTurnEnd transitions the session phase to IDLE and dispatches turn-end actions.
852	func transitionSessionTurnEnd(ctx context.Context, sessionID string, event *agent.Event) {
853		logCtx := logging.WithComponent(ctx, "lifecycle")
854		turnState, loadErr := strategy.LoadSessionState(ctx, sessionID)
855		if loadErr != nil {
856			logging.Warn(logCtx, "failed to load session state for turn end",
857				slog.String("error", loadErr.Error()))
858			return
859		}
860		if turnState == nil {
861			return
862		}
863	
864		persistEventMetadataToState(event, turnState)
865	
866		if err := strategy.TransitionAndLog(ctx, turnState, session.EventTurnEnd, session.TransitionContext{}, session.NoOpActionHandler{}); err != nil {
867			logging.Warn(logCtx, "turn-end transition failed",
868				slog.String("error", err.Error()))
869		}
870	
871		// Always dispatch to strategy for turn-end handling. The strategy reads
872		// work items from state (e.g. TurnCheckpointIDs), not the action list.
873		strat := GetStrategy(ctx)
874		if err := strat.HandleTurnEnd(ctx, turnState); err != nil {
875			logging.Warn(logCtx, "turn-end action dispatch failed",
876				slog.String("error", err.Error()))
877		}
878	
879		if updateErr := strategy.SaveSessionState(ctx, turnState); updateErr != nil {
880			logging.Warn(logCtx, "failed to update session phase on turn end",
881				slog.String("error", updateErr.Error()))
882		}
883	}
884	
885	// markSessionEnded transitions the session to ENDED phase via the state machine.
886	// If event is non-nil, hook-provided metrics are persisted to state before saving.
887	func markSessionEnded(ctx context.Context, event *agent.Event, sessionID string) error {
888		state, err := strategy.LoadSessionState(ctx, sessionID)
889		if err != nil {
890			return fmt.Errorf("failed to load session state: %w", err)
891		}
892		if state == nil {
893			return nil // No state file, nothing to update
894		}
895	
896		if event != nil {
897			persistEventMetadataToState(event, state)
898		}
899	
900		if transErr := strategy.TransitionAndLog(ctx, state, session.EventSessionStop, session.TransitionContext{}, session.NoOpActionHandler{}); transErr != nil {
901			logging.Warn(logging.WithComponent(ctx, "lifecycle"), "session stop transition failed",
902				slog.String("error", transErr.Error()))
903		}
904	
905		now := time.Now()
906		state.EndedAt = &now
907	
908		if err := strategy.SaveSessionState(ctx, state); err != nil {
909			return fmt.Errorf("failed to save session state: %w", err)
910		}
911		return nil
912	}
913	
914	// logFileChanges logs the files modified, created, and deleted during a session.
915	func logFileChanges(ctx context.Context, modified, newFiles, deleted []string) {
916		logCtx := logging.WithComponent(ctx, "lifecycle")
917		logging.Debug(logCtx, "files changed during session",
918			slog.Int("modified", len(modified)),
919			slog.Int("new", len(newFiles)),
920			slog.Int("deleted", len(deleted)))
921	}
922	
923	func persistEventMetadataToState(event *agent.Event, state *strategy.SessionState) {
924		// Update ModelName if provided (model is known by turn-end even on first turn)
925		if event.Model != "" {
926			state.ModelName = event.Model
927		}
928	
929		// Persist hook-provided session metrics (e.g., from Cursor hooks)
930		if event.DurationMs > 0 {
931			state.SessionDurationMs = event.DurationMs
932		}
933		// Use hook-reported turn count if available (take max); otherwise
934		// increment on each TurnEnd event to count turns ourselves.
935		if event.TurnCount > 0 {
936			if event.TurnCount > state.SessionTurnCount {
937				state.SessionTurnCount = event.TurnCount
938			}
939		} else if event.Type == agent.TurnEnd {
940			state.SessionTurnCount++
941		}
942		if event.ContextTokens > 0 {
943			state.ContextTokens = event.ContextTokens
944		}
945		if event.ContextWindowSize > 0 {
946			state.ContextWindowSize = event.ContextWindowSize
947		}
948	}
949

