58	// --- Transcript Storage ---
59	
60	// ReadTranscript reads the transcript for a session.
61	// The sessionRef is expected to be a path to the export JSON file.
62	func (a *OpenCodeAgent) ReadTranscript(sessionRef string) ([]byte, error) {
63		data, err := os.ReadFile(sessionRef) //nolint:gosec // Path from agent hook
64		if err != nil {
65			return nil, fmt.Errorf("failed to read opencode transcript: %w", err)
66		}
67		return data, nil
68	}
69	
70	// ChunkTranscript splits an OpenCode export JSON transcript by distributing messages across chunks.
71	// OpenCode uses JSON format with {"info": {...}, "messages": [...]} structure.
72	func (a *OpenCodeAgent) ChunkTranscript(_ context.Context, content []byte, maxSize int) ([][]byte, error) {
73		var session ExportSession
74		if err := json.Unmarshal(content, &session); err != nil {
75			return nil, fmt.Errorf("failed to parse export session for chunking: %w", err)
76		}
77	
78		if len(session.Messages) == 0 {
79			return [][]byte{content}, nil
80		}
81	
82		// Marshal info to calculate accurate base size
83		infoBytes, err := json.Marshal(session.Info)
84		if err != nil {
85			return nil, fmt.Errorf("failed to marshal session info for chunking: %w", err)
86		}
87		// Base JSON structure size: {"info":<info>,"messages":[ ... ]}
88		baseSize := len(`{"info":`) + len(infoBytes) + len(`,"messages":[]}`)
89	
90		var chunks [][]byte
91		var currentMessages []ExportMessage
92		currentSize := baseSize
93	
94		for _, msg := range session.Messages {
95			// Marshal message to get its size
96			msgBytes, err := json.Marshal(msg)
97			if err != nil {
98				return nil, fmt.Errorf("failed to marshal message for chunking: %w", err)
99			}
100			msgSize := len(msgBytes) + 1 // +1 for comma separator
101	
102			if currentSize+msgSize > maxSize && len(currentMessages) > 0 {
103				// Save current chunk
104				chunkData, err := json.Marshal(ExportSession{Info: session.Info, Messages: currentMessages})
105				if err != nil {
106					return nil, fmt.Errorf("failed to marshal chunk: %w", err)
107				}
108				chunks = append(chunks, chunkData)
109	
110				// Start new chunk
111				currentMessages = nil
112				currentSize = baseSize
113			}
114	
115			currentMessages = append(currentMessages, msg)
116			currentSize += msgSize
117		}
118	
119		// Add the last chunk
120		if len(currentMessages) > 0 {
121			chunkData, err := json.Marshal(ExportSession{Info: session.Info, Messages: currentMessages})
122			if err != nil {
123				return nil, fmt.Errorf("failed to marshal final chunk: %w", err)
124			}
125			chunks = append(chunks, chunkData)
126		}
127	
128		if len(chunks) == 0 {
129			return nil, errors.New("failed to create any chunks")
130		}
131	
132		return chunks, nil
133	}
134	
135	// ReassembleTranscript merges OpenCode export JSON chunks by combining their message arrays.
136	func (a *OpenCodeAgent) ReassembleTranscript(chunks [][]byte) ([]byte, error) {
137		if len(chunks) == 0 {
138			return nil, errors.New("no chunks to reassemble")
139		}
140	
141		var allMessages []ExportMessage
142		var sessionInfo SessionInfo
143	
144		for i, chunk := range chunks {
145			var session ExportSession
146			if err := json.Unmarshal(chunk, &session); err != nil {
147				return nil, fmt.Errorf("failed to unmarshal chunk %d: %w", i, err)
148			}
149			if i == 0 {
150				sessionInfo = session.Info // Preserve session info from first chunk
151			}
152			allMessages = append(allMessages, session.Messages...)
153		}
154	
155		result, err := json.Marshal(ExportSession{Info: sessionInfo, Messages: allMessages})
156		if err != nil {
157			return nil, fmt.Errorf("failed to marshal reassembled transcript: %w", err)
158		}
159		return result, nil
160	}
161	
162	// --- Legacy methods ---
163	
164	func (a *OpenCodeAgent) GetSessionID(input *agent.HookInput) string {
165		return input.SessionID
166	}
167	
168	// GetSessionDir returns the directory where Entire stores OpenCode session transcripts.
169	// Transcripts are ephemeral handoff files between the TS plugin and the Go hook handler.
170	// Once checkpointed, the data lives on git refs and the file is disposable.
171	// Stored in os.TempDir()/entire-opencode/<sanitized-path>/ to avoid squatting on
172	// OpenCode's own directories (~/.opencode/ is project-level, not home-level).
173	func (a *OpenCodeAgent) GetSessionDir(repoPath string) (string, error) {
174		// Check for test environment override
175		if override := os.Getenv("ENTIRE_TEST_OPENCODE_PROJECT_DIR"); override != "" {
176			return override, nil
177		}
178	
179		projectDir := SanitizePathForOpenCode(repoPath)
180		return filepath.Join(os.TempDir(), "entire-opencode", projectDir), nil
181	}
182	
183	func (a *OpenCodeAgent) ResolveSessionFile(sessionDir, agentSessionID string) string {
184		return filepath.Join(sessionDir, agentSessionID+".json")
185	}
186	
187	func (a *OpenCodeAgent) ReadSession(input *agent.HookInput) (*agent.AgentSession, error) {
188		if input.SessionRef == "" {
189			return nil, errors.New("no session ref provided")
190		}
191		data, err := os.ReadFile(input.SessionRef)
