238			// Non-fatal: session might not exist yet (first session).
239			// Import will still work for new sessions; only rewind of existing sessions
240			// would have stale messages.
241			logging.Warn(ctx, "could not delete existing opencode session",
242				slog.String("session_id", sessionID),
243				slog.String("error", err.Error()),
244			)
245		}
