+	if len(names) != len(expected) {
+		t.Fatalf("expected %d hook names, got %d", len(expected), len(names))
+	}
+
+	nameSet := make(map[string]bool)
+	for _, n := range names {
+		nameSet[n] = true
+	}
+	for _, e := range expected {
+		if !nameSet[e] {
+			t.Errorf("missing expected hook name: %s", e)
+		}
+	}
+}
